"""`.Toon shading`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Toon shading'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Toon shading', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Normal passthrough', 'NodeSocketColor')
